// Parse extracted customer data safely
const data = JSON.parse($node["Customer & Vehicle & Language Details Extractor"].json["output"] || '{}');
const name = data.name?.trim();
const email = data.email?.trim();

// Get context from "Extracting the context" node
const context = $node["Extracting the context"].json?.context ?? null;

// Try to access "Extracting the context1" only if it exists
let context1 = null;
try {
  context1 = $node["Extracting the context1"]?.json?.context ?? null;
} catch (error) {
  // If node doesn't exist or didn't run, context1 remains null
  context1 = null;
}

// Determine if lead should be created
const create_lead = context === null && context1 === null;

// Determine if lead should be updated
const update_lead = !create_lead && (Boolean(name) || Boolean(email));

return {
  json: {
    create_lead: Boolean(create_lead),
    update_lead: Boolean(update_lead)
  }
};

// Helper to normalize is_note truthiness
const isNoteTrue = (val) => {
  return val === true || val === 'true' || val === 1 || val === '1' || String(val).toLowerCase() === 'true';
};

const items = $items("Check DB for existing query");

if (!items || items.length === 0) {
  return [
    {
      json: {
        parent_id: null,
        reason: "No previous messages found"
      }
    }
  ];
}

// 🔥 Step 1: Filter out notes
const filteredItems = items.filter(item => {
  return !isNoteTrue(item.json.isNote);
});

if (!filteredItems || filteredItems.length === 0) {
  return [
    {
      json: {
        parent_id: null,
        reason: "Only notes found, no valid messages"
      }
    }
  ];
}

// 🔥 Step 2: Sort remaining messages (latest first)
const sortedItems = filteredItems.sort((a, b) => {
  return new Date(b.json.timestamp) - new Date(a.json.timestamp);
});

// Step 3: Extract latest message
const latest = sortedItems[0]?.json || {};

// Step 4: Determine parent_id
let parent_id = latest.parent_message_id;
if (!parent_id) {
  parent_id = latest.message_id;
}

// Step 5: Return output
return [
  {
    json: {
      parent_id
    }
  }
];

return [{
    message: $node["Extract Booking Response"].json["message"].slice(0, 300) // Trim increased to 300 chars to acomodate VDP url
}];

const dealerTimeZone = $node["Set Bot Name & Store No & Store Address"].json["Store Timezone"];
const now = new Date();

// Format the date and time
const date = now.toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: dealerTimeZone
});

const time = now.toLocaleTimeString('en-US', {
  hour: '2-digit',
  minute: '2-digit',
  timeZone: dealerTimeZone
});

// Save it to be used in the prompt
return [
  {
    json: {
      todayDate: date,
      currentTime: time,
    }
  }
];

// Get values from previous nodes
const appointmentStatusRaw = $node["FE Lead Appointment Status"].json["output"];
const createLead = $node["Create or Update Lead Status"].json["create_lead"];

// Clean and parse the appointment status string (strip markdown formatting)
const jsonString = appointmentStatusRaw
  .replace(/```json\n?/, '')
  .replace(/\n?```/, '');

// Parse the appointment status JSON (because it is a stringified JSON)
const appointmentStatus = JSON.parse(jsonString).appointment_status;

// Appointment cancellation boolean flag
const appointment_cancellation_requested =
  appointmentStatus === "Appointment Cancellation Requested";

let fe_lead;

// Logic to determine fe_lead
if (appointmentStatus == "Appointment Booked" || appointmentStatus === "Managerial Review") {
  fe_lead = appointmentStatus;
} else {
  if (createLead === "true") {
    fe_lead = "Lead";
  } else {
    fe_lead = "Contacted";
  }
}

// Return the result
return [
  {
    json: {
      fe_lead: fe_lead,
      appointment_cancellation_requested
    }
  }
];

// Get values from previous nodes
const appointmentStatusRaw = $node["FE Lead Appointment Status2"].json["output"];
const createLead = $node["Create or Update Lead Status"].json["create_lead"];

// Clean and parse the appointment status string (strip markdown formatting)
const jsonString = appointmentStatusRaw
  .replace(/```json\n?/, '')
  .replace(/\n?```/, '');

// Parse the appointment status JSON (because it is a stringified JSON)
const appointmentStatus = JSON.parse(jsonString).appointment_status;

// Appointment Cancellation boolean flag
const appointment_cancellation_requested =
  appointmentStatus === "Appointment Cancellation Requested";

let fe_lead;

// Logic to determine fe_lead
if (appointmentStatus == "Appointment Booked" || appointmentStatus === "Managerial Review") {
  fe_lead = appointmentStatus;
} else {
  if (createLead === "true") {
    fe_lead = "Lead";
  } else {
    fe_lead = "Contacted";
  }
}

// Return the result
return [
  {
    json: {
      fe_lead: fe_lead,
      appointment_cancellation_requested
    }
  }
];

return [
  {
    json: {
      htmlBody: `<html>
  <body style="font-family: Arial, sans-serif; font-size: 14px; color: #333; line-height: 1.6;">
    ${
      ($node["Extract Email Response & Body"].json["email_response"] || "")
        // **bold** -> <strong>
        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
        // remove any existing <a>...</a> but keep inner text
        .replace(/<a\b[^>]*>(.*?)<\/a>/gi, '$1')
        // split paras on blank lines OR <br><br>
        .split(/(?:\n\s*\n|<br\s*\/?>\s*<br\s*\/?>)/i)
        .map(p => `<div style="margin-bottom: 12px;">${
          p
            // keep single line breaks
            .replace(/\n/g, '<br>')
            // linkify plain URLs once
            .replace(
              /((https?:\/\/)?(?:www\.)?[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}(\/[^\s<]*)?)/g,
              (match, url) => {
                const href = /^https?:\/\//.test(url) ? url : `https://${url}`;
                return `<a href="${href}" target="_blank">${url}</a>`;
              }
            )
        }</div>`).join("")
    }
  </body>
</html>`
    }
  }
];

let output = $json.output || '';
let parsed = {};

try {
  // If the output is a string, clean it
  if (typeof output === 'string') {
    // Remove markdown code block wrapping (e.g., ```json ... ```)
    output = output.replace(/```(?:json)?\s*/gi, '').replace(/```$/, '').trim();

    // Remove excessive newlines
    output = output.replace(/\\n/g, '').replace(/\n/g, '').trim();

    // Try parsing cleaned JSON string
    parsed = JSON.parse(output);
  } else {
    parsed = output;
  }
} catch (e) {
  parsed = {};
}

// Helper to safely clean string fields
const cleanField = (str) =>
  typeof str === 'string'
    ? str.replace(/\\n/g, '').replace(/\n/g, '').trim()
    : '';

const email_response = cleanField(parsed.email_response);
const email_subject = cleanField(parsed.email_subject);

return [
  {
    json: {
      email_response,
      email_subject
    }
  }
];

// Assumes input is from MongoDB node
return items.map(item => {
  return {
    json: {
      vin: item.json.vin || 'VIN not found',
      name: item.json.name || 'Name not found',
      email: item.json.email || 'Email not found'
    }
  };
});

let contextArray = items.map((item, index) => {
  const message = item.json.mail_content;
  const timestamp = item.json.timestamp;
  const status = item.json.status;
  const response = item.json.api_response?.Response || null;

  if (status === "incoming" && message && timestamp) {
    return `Conversation ${index + 1}:\nMessage (Received): "${message}"\nCreated At: "${timestamp}"`;
  } else if (status === "sent" && response && timestamp) {
    return `Conversation ${index + 1}:\nResponse (Sent): "${response}"\nCreated At: "${timestamp}"`;
  } else if (status === "failed" && message && timestamp) {
    return `Conversation ${index + 1}:\nMessage (Failed to Send): "${message}"\nCreated At: "${timestamp}"`;
  } else {
    return null;
  }
}).filter(Boolean); // Remove nulls

let contextString = contextArray.length > 0 ? contextArray.join("\n\n") : null;

return [{ json: { context: contextString } }];

const item = items[0].json;

const vehicleData = {
  year: item.year || null,
  make: item.make || null,
  model: item.model || null,
  trim: item.trim || null,
  body: item.body || null,
  vehicletype: item.vehicletype || null,
  vehicleclass: item.vehicleclass || null,
  newused: item.newused || null,
  title: item.title || null,

  engine: item.engine || null,
  transmission: item.transmission || null,
  drive: item.drive || null,
  mileage: item.mileage || null,
  fuel: item.fuel || null,

  exteriorcolor: item.exteriorcolor || null,
  interiorcolor: item.interiorcolor || null,
  seats: item.seats || null,

  price: item.internetprice || null,

  vdplink: item.shortUrl || null
};

return [
  {
    json: {
      ...vehicleData,
      vehicle_info: JSON.stringify(vehicleData, null, 2)  // formatted string
    }
  }
];

let contextSMS = null;
let contextEmail = null;
let contextAttachments = null;
let contextCampaign = null;

/* -----------------------------
   SMS context (UNCHANGED)
-------------------------------- */
try {
  contextSMS = $node["Extracting the context"].json.context || null;
} catch (e) {
  contextSMS = null;
}

/* -----------------------------
   Email context (UNCHANGED)
-------------------------------- */
try {
  contextEmail = $node["Extracting the context1"].json.context || null;
} catch (e) {
  contextEmail = null;
}

/* -----------------------------
   Attachment context (NEW)
   Comes from attachment pipeline
-------------------------------- */
try {
  contextAttachments =
    $node["Build Response Context"].json.combined_context || null;
} catch (e) {
  contextAttachments = null;
}
/* -----------------------------
   Campaign context
   Comes from "Extracting the latest campaign details"
-------------------------------- */
try {
  const campaignNode =
    $node["Extracting the latest campaign details"].json;

  if (campaignNode?.has_campaign_context) {
    contextCampaign = `
        Campaign Name: ${campaignNode.campaign_name || "Unknown"}
        Campaign Subject: ${campaignNode.campaign_subject || "N/A"}
        Campaign Sent At: ${campaignNode.campaign_sent_at || "Unknown"}

        Campaign Message:
        ${campaignNode.campaign_body || "No campaign body available."}
        `.trim();
  } else {
    contextCampaign = null;
  }
} catch (e) {
  contextCampaign = null;
}

/* -----------------------------
   Normalize + metadata
-------------------------------- */
const safeSMS =
  contextSMS && contextSMS.trim().length > 0
    ? contextSMS
    : "No previous SMS conversation found.";

const safeEmail =
  contextEmail && contextEmail.trim().length > 0
    ? contextEmail
    : "No previous email communication found.";

const safeAttachments =
  contextAttachments && contextAttachments.trim().length > 0
    ? contextAttachments
    : null;

const safeCampaign =
  contextCampaign && contextCampaign.trim().length > 0
    ? contextCampaign
    : null;

/* -----------------------------
   Final guaranteed output
-------------------------------- */
return [
  {
    json: {
      safe_sms_context: safeSMS,
      safe_email_context: safeEmail,
      safe_attachment_context: safeAttachments,
      safe_campaign_context: safeCampaign,

      // extremely useful downstream
      context_meta: {
        has_sms: !!contextSMS,
        has_email: !!contextEmail,
        has_attachments: !!contextAttachments,
        has_campaign: !!contextCampaign
      }
    }
  }
];

// Attempt to access the vehicle inventory from "Format Inventory Summary"
let vehicleInfo = "Vehicle information not available.";
try {
  const inventory = $node["Format Inventory Summary"];
  if (inventory && inventory.json && inventory.json.vehicle_info) {
    vehicleInfo = inventory.json.vehicle_info;
  }
} catch (e) {
  // Leave as default
}

return [{
  json: {
    safe_vehicle_info: vehicleInfo
  }
}];

