xml = xml.replace(/<!\[CDATA\[[\s\S]*?\]\](?!>)/g, m => m + '>');

// Temporarily escape ampersands not in valid entities or CDATA
xml = xml.replace(/<!\[CDATA\[(.*?)\]\]>/gs, (match, inner) => {
