const normalizeSubject = (str) => {
  if (!str) return '';
  return str
    .toLowerCase()
    .replace(/^((re|fw|fwd):\s*)+/gi, '')
    .replace(/\[[^\]]*]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

const incomingSubject = normalizeSubject(
  $node["Input Extraction"].json.subject
);

let matchedCampaign = null;

for (const item of items) {
  const rawSubject = item.json?.message_content?.subject;
  const campaignSubject = normalizeSubject(rawSubject);

  if (campaignSubject && campaignSubject === incomingSubject) {
    matchedCampaign = item.json;
    break;
  }
}

return [{
  json: {
    is_campaign_match: !!matchedCampaign,
    campaign_id: matchedCampaign?._id || null,
    campaign_name: matchedCampaign?.name || null,
    campaign_subject: matchedCampaign?.message_content?.subject || null,
    campaign_body: matchedCampaign?.message_content?.body || null,
    use_replies_for_ai: matchedCampaign?.settings?.use_replies_for_ai ?? null
  }
}];

