let output = $json.output || '';
let parsed = {};

try {
  // Remove newlines before parsing if it's a string
  if (typeof output === 'string') {
    parsed = JSON.parse(output.replace(/\n/g, '').trim());
  } else {
    parsed = output;
  }
} catch (e) {
  parsed = {};
}

// Safely extract and clean
const email_response = parsed.email_response?.replace(/\n/g, '').replace(/\\n/g, '').trim() || '';
const email_subject = parsed.email_subject?.replace(/\n/g, '').replace(/\\n/g, '').trim() || '';

return [
  {
    json: {
      email_response,
      email_subject
    }
  }
];

return [
  {
    json: {
      htmlBody: `<html>
  <body style="font-family: Arial, sans-serif; font-size: 14px; color: #333; line-height: 1.6;">
    ${
      ($node["Extract Email Response & Body3"].json["email_response"] || "")
        // **bold** -> <strong>
        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
        // remove any existing <a>...</a> but keep inner text
        .replace(/<a\b[^>]*>(.*?)<\/a>/gi, '$1')
        // split paras on blank lines OR <br><br>
        .split(/(?:\n\s*\n|<br\s*\/?>\s*<br\s*\/?>)/i)
        .map(p => `<div style="margin-bottom: 12px;">${
          p
            // keep single line breaks
            .replace(/\n/g, '<br>')
            // linkify plain URLs once
            .replace(
              /((https?:\/\/)?(?:www\.)?[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}(\/[^\s<]*)?)/g,
              (match, url) => {
                const href = /^https?:\/\//.test(url) ? url : `https://${url}`;
                return `<a href="${href}" target="_blank">${url}</a>`;
              }
            )
        }</div>`).join("")
    }
  </body>
</html>`
    }
  }
];

const email = $node["Email Trigger"].json.body.currentEmail;

const attachments = (email.attachments || []).map(a => ({
  filename: a.filename,
  content_type: a.contentType,
  size: a.size,
  url: a.url,
  s3_key: a.s3Key,
  uploaded_at: a.uploadedAt
}));

return [{
  sender: email.sender,
  subject: email.subject,
  dealer_id: email.dealer_id,
  has_attachments: email.has_attachments,
  attachments
}];

const attachments =
  $node["Extract Attachments"]?.json?.attachments || [];
const attachment_index = {
  images: [],
  videos: [],
  documents: [],
  audio: [],
  archives: [],
  others: []
};

for (const a of attachments) {
  const name = (a.filename || "").toLowerCase();
  const type = (a.contentType || a.content_type || "").toLowerCase();

  if (type.startsWith("image/") || name.match(/\.(jpg|jpeg|png|webp|gif)$/i)) {
    attachment_index.images.push(a);
    continue;
  }

  if (type.startsWith("video/") || name.match(/\.(mp4|mov|avi|mkv)$/i)) {
    attachment_index.videos.push(a);
    continue;
  }

  if (
    type === "application/pdf" ||
    type.startsWith("text/") ||
    name.match(/\.(pdf|txt|csv|doc|docx|xls|xlsx|ppt|pptx)$/i)
  ) {
    attachment_index.documents.push(a);
    continue;
  }

  if (type.startsWith("audio/") || name.match(/\.(mp3|wav|m4a|aac)$/i)) {
    attachment_index.audio.push(a);
    continue;
  }

  if (name.match(/\.(zip|rar|7z)$/i)) {
    attachment_index.archives.push(a);
    continue;
  }

  attachment_index.others.push(a);
}

return [{
  ...$json,
  attachment_index
}];

const idx =
  $node["Classify Attachments"]?.json?.attachment_index;
const flat = [];

for (const a of idx.images)     flat.push({ ...a, modality: "image" });
for (const a of idx.documents)  flat.push({ ...a, modality: "document" });
for (const a of idx.videos)     flat.push({ ...a, modality: "video" });
for (const a of idx.audio)      flat.push({ ...a, modality: "audio" });
for (const a of idx.archives)   flat.push({ ...a, modality: "archive" });
for (const a of idx.others)     flat.push({ ...a, modality: "other" });

return flat.map(a => ({ json: a }));

const raw = $json.content?.[0]?.text || "";

const cleaned = raw
  .replace(/^```json\s*/i, "")
  .replace(/```$/i, "")
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Invalid JSON from image analyzer");
}

return [{
  modality: "image",
  filename: $json.filename,
  insights: parsed
}];

const i = $json.insights;

return [{
  modality: "image",
  filename: $json.filename,
  insights: {
    vehicle_present: i.vehicle_present ?? false,
    vehicle_type: i.vehicle_type ?? null,
    brand: i.brand_visible ?? null,
    visible_damage: i.visible_damage ?? null,
    confidence: i.confidence ?? null
  }
}];

const items = $items(); // safe even if empty

const image_insights = [];
const document_insights = [];

for (const item of items) {
  const d = item.json || {};

  if (d.modality === "image") {
    image_insights.push({
      filename: d.filename || null,
      insights: d.insights || null
    });
  }

  if (d.modality === "document") {
    document_insights.push({
      filename: d.filename || null,
      insights: d.insights || null
    });
  }
}

// ALWAYS return exactly ONE item
return [{
  image_insights,
  document_insights,
  has_attachments: image_insights.length + document_insights.length > 0
}];

const agg = $node["Aggregate AI Insights"]?.json;

const images = agg?.image_insights || [];
const docs = agg?.document_insights || [];

let context = "";

if (images.length > 0) {
  context += "IMAGE ANALYSIS:\n";
  images.forEach((img, i) => {
    context += `Image ${i + 1}: ${JSON.stringify(img.insights)}\n`;
  });
}

if (docs.length > 0) {
  context += "\nDOCUMENT ANALYSIS:\n";
  docs.forEach((doc, i) => {
    context += `Document ${i + 1}: ${JSON.stringify(doc.insights)}\n`;
  });
}

return [{
  combined_context: context.trim() || null,
  has_attachments: agg?.has_attachments ?? false
}];

const buffer = Buffer.from($binary.data.data, "base64");
const text = buffer.toString("utf-8");

return [{
  extracted_text: text
}];

const buffer = Buffer.from($binary.data.data, "base64");
