// If <email> exists → use it, else fallback to whole string
const cleanEmail = match ? match[1] : rawSender.trim();

return [
  {
    json: {
      ...$json,
      clean_email: cleanEmail.toLowerCase()
    }
  }
];

const campaignObjects = $json.campaign_object_ids || [];

const campaignIds = campaignObjects
  .map(c => c.$oid)
  .filter(Boolean);

return [
  {
    json: {
      ...$json,
      campaign_ids_clean: campaignIds
    }
  }
];

// Always normalize to array
const ids = Array.isArray($json.campaign_ids_clean)
  ? $json.campaign_ids_clean
  : [$json.campaign_ids_clean];

// Build MongoDB-safe query object
return [
