const jsonString = appointmentStatusRaw
  .replace(/```json\n?/, '')
  .replace(/\n?```/, '');

const appointmentStatus = JSON.parse(jsonString).appointment_status;

let fe_lead;

// Logic to determine fe_lead
if (appointmentStatus == "Appointment Bookedt") {
  fe_lead = appointmentStatus;
} else {
  if (createLead === "true") {
    fe_lead = "Lead";
  } else {
    fe_lead = "Contacted";
  }
}

// Return the result
return [
  {
    json: {
      fe_lead: fe_lead
    }
  }
];

